            into[prop] = 'react' if into.get(prop) == 'react' or declared_in_react(info) else 'own'
    items = [{'keys': list(dict.fromkeys(g['keys'])), 'props': g['exact'] or g['other']} for g in groups.values()]
    for g, item in zip(groups.values(), items):
        if not any(k in found for k in item['keys']):
            cause = classify(g['comp'], g['rel'], res, g['cause'], collisions)
            stats['unmatched'][cause] = stats['unmatched'].get(cause, 0) + 1
            unmatched.append((g['rel'], g['comp']['name'], cause, len(item['props'])))
    stats['reference'] = len(items)
    stats['unpaired'] = len(unmatched)
    stats['excluded_total'] = sum(stats['excluded'].values())
    return items, stats, unmatched

